export default function App() {
  const { width } = useWindowDimensions();
  const isDesktop = width >= 900;

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);

  const LeftSidebar = (
    <View style={[styles.sidebar, isDesktop ? styles.sidebarDesktop : styles.sidebarMobile]}>
      {/* Brand Header */}
      <View style={styles.brandRow}>
        <View style={styles.logoBox}>
          <View style={styles.logoInner} />
        </View>
        <Text style={styles.brandName}>Nimbus</Text>
      </View>

      {/* Quote */}
      <View style={styles.quoteContainer}>
        <Text style={styles.quoteText}>
          “We stopped losing tasks in Slack threads the week we moved to Nimbus.”
        </Text>
        <Text style={styles.quoteAuthor}>
          Priya Raman, Engineering Lead at Fernway
        </Text>
      </View>
    </View>
  );

  const LoginForm = (
    <View style={[styles.formWrapper, isDesktop ? styles.formWrapperDesktop : styles.formWrapperMobile]}>
      <View style={styles.formContainer}>
        <Text style={styles.heading}>Log in to Nimbus</Text>
        <Text style={styles.subheading}>
          Welcome back. Pick up where your team left off.
        </Text>

        {/* Inputs */}
        <View style={styles.fieldGroup}>
          <Text style={styles.label}>Work email</Text>
          <TextInput
            style={styles.input}
            placeholder="you@company.com"
            placeholderTextColor="#94a3b8"
            keyboardType="email-address"
            autoCapitalize="none"
            value={email}
            onChangeText={setEmail}
          />
        </View>

        <View style={styles.fieldGroup}>
          <Text style={styles.label}>Password</Text>
          <TextInput
            style={styles.input}
            placeholder="••••••••••"
            placeholderTextColor="#94a3b8"
            secureTextEntry
            value={password}
            onChangeText={setPassword}
          />
        </View>

        {/* Options Row */}
        <View style={styles.optionsRow}>
          <Pressable
            style={styles.checkboxContainer}
            onPress={() => setRememberMe(!rememberMe)}
          >
            <View style={[styles.checkbox, rememberMe && styles.checkboxActive]}>
              {rememberMe && <View style={styles.checkboxCheck} />}
            </View>
            <Text style={styles.checkboxLabel}>Remember me</Text>
          </Pressable>

          <Pressable onPress={() => {}}>
            <Text style={styles.forgotPassword}>Forgot password?</Text>
          </Pressable>
        </View>

        {/* Submit */}
        <Pressable style={styles.primaryButton} onPress={() => {}}>
          <Text style={styles.primaryButtonText}>Log in</Text>
        </Pressable>

        {/* Divider */}
        <View style={styles.dividerRow}>
          <View style={styles.dividerLine} />
          <Text style={styles.dividerText}>or</Text>
          <View style={styles.dividerLine} />
        </View>

        {/* Google OAuth Button */}
        <Pressable style={styles.googleButton} onPress={() => {}}>
          <View style={styles.googleIconCircle}>
            <View style={[styles.gSegment, { backgroundColor: '#EA4335' }]} />
            <View style={[styles.gSegment, { backgroundColor: '#4285F4' }]} />
            <View style={[styles.gSegment, { backgroundColor: '#34A853' }]} />
            <View style={[styles.gSegment, { backgroundColor: '#FBBC05' }]} />
          </View>
          <Text style={styles.googleButtonText}>Continue with Google</Text>
        </Pressable>

        {/* Footer */}
        <View style={styles.footerRow}>
          <Text style={styles.footerText}>New to Nimbus? </Text>
          <Pressable onPress={() => {}}>
            <Text style={styles.footerLink}>Create an account</Text>
          </Pressable>
        </View>
      </View>
    </View>
  );

  return (
    <SafeAreaView style={styles.screen}>
      {isDesktop ? (
        <View style={styles.desktopContainer}>
          {LeftSidebar}
          {LoginForm}
        </View>
      ) : (
        <ScrollView contentContainerStyle={styles.mobileScrollContainer}>
          {LeftSidebar}
          {LoginForm}
        </ScrollView>
      )}
    </SafeAreaView>
  );
}

